const AIRPORT_STATIONS=new Set([
 'Yuchow Airport','Songqiao Airport','Alderford Airport','Newport',
 'Aéroport Parnay','Cartier','Cosgrove','Medway Airport','Atlantic Airport',
 'Findel','Chiangkou'
]);
// Staffed services and facilities with opening hours, by station tier (minutes past midnight; null = closed that day).
const RR_H=(a,b)=>[a*60,b*60];
const RR_DAILY=(a,b)=>({wk:RR_H(a,b),sat:RR_H(a,b),sun:RR_H(a,b)});
const STATION_HOURS={
 national:{'RR Services':RR_DAILY(5.5,23.5),'Police':RR_DAILY(0,24),'Mobility assistance':RR_DAILY(5,24),'First Class lounge':{wk:RR_H(5.5,22),sat:RR_H(6,22),sun:RR_H(6,22)},
  'Lost property':{wk:RR_H(8,19),sat:RR_H(9,17),sun:null},'Café':{wk:RR_H(5.5,22),sat:RR_H(6,22),sun:RR_H(7,21)},'Luggage':{wk:RR_H(6,23),sat:RR_H(6,23),sun:RR_H(7,22)}},
 major:{'RR Services':{wk:RR_H(6,22),sat:RR_H(7,21),sun:RR_H(7,21)},'Police':{wk:RR_H(7,23),sat:RR_H(7,23),sun:RR_H(8,22)},'Mobility assistance':{wk:RR_H(6,22),sat:RR_H(7,21),sun:RR_H(7,21)},
  'Lost property':{wk:RR_H(9,17),sat:null,sun:null},'Café':{wk:RR_H(6,21),sat:RR_H(7,20),sun:RR_H(8,20)},'Luggage':{wk:RR_H(7,21),sat:RR_H(8,20),sun:RR_H(8,20)}},
 regional:{'RR Services':{wk:RR_H(6.5,19.5),sat:RR_H(8,16),sun:null},'Café':{wk:RR_H(6.5,19),sat:RR_H(8,17),sun:null}},
 local:{'Café':{wk:RR_H(7,14),sat:null,sun:null}}
};
const STATION_HELP=['RR Services','Police','Mobility assistance','First Class lounge','Lost property'];
const RR_FAC_NOTE={'RR Services':'Tickets, travel advice and help with your journey','Police':'Run by the Federal Police','Mobility assistance':'Help getting on and off trains',
 'First Class lounge':'For First Class ticket holders','Lost property':'Items found on trains and at the station','Café':'Food and drinks','Luggage':'Left luggage'};
// Facility faults: on a given day about 7% of stations have one lift, escalator or toilet out of order (date seed,
// so everyone sees the same faults today). Shown with an amber light and the issue in the facility's panel.
const RR_FAULTS={Lift:['Out of order','The lift to the platforms is out of order. Step-free access: ask RR staff for help or use the next station.'],
 Escalator:['Out of order','The escalator is stopped for repairs. Please use the stairs or the lift.'],
 'Accessible Toilet':['Closed','The accessible toilet is closed for repairs.'],Toilet:['Closed','The toilets are closed for cleaning.']};
function rrStationFault(name){
 const h=rrHash(RR_DAY_KEY+'|fault|'+name);if(h%100>=7)return null;
 const fac=stationFacilities(name).filter(f=>RR_FAULTS[f]);if(!fac.length)return null;
 const f=fac[(h>>>8)%fac.length],back=(8+(h>>>12)%12)*60;
 return {facility:f,title:RR_FAULTS[f][0],text:RR_FAULTS[f][1],back};
}
function rrStationTier(name){return NATIONAL_HUBS.has(name)?'national':MAJOR_STATIONS.has(name)?'major':(REGIONAL_INTERCHANGES.has(name)||AIRPORT_STATIONS.has(name))?'regional':'local'}
function rrHoursOn(h,day){return day===0?h.sun:day===6?h.sat:h.wk}
function rrClock(m){return m>=1440&&!RR_SHOW_SHIFT?'24:00':rrMinutesToInput(rrShowMinutes(m))}
function rrOpenStatus(h){
 const d=rrNow(),day=d.getDay(),now=d.getHours()*60+d.getMinutes(),t=rrHoursOn(h,day);
 if(t&&t[0]===0&&t[1]>=1440)return{open:true,text:'Open 24 hours'};
 if(t&&now>=t[0]&&now<t[1])return{open:true,text:'Open now · closes '+rrClock(t[1])};
 for(let k=0;k<8;k++){const dd=(day+k)%7,tt=rrHoursOn(h,dd);if(!tt||(k===0&&now>=tt[0]))continue;
  return{open:false,text:'Closed · opens '+(k===0?'':k===1?'tomorrow ':RR_DAYS[dd].slice(0,3)+' ')+rrClock(tt[0])}}
 return{open:false,text:'Closed'};
}
function rrHoursRows(h){
 const f=t=>!t?'Closed':t[0]===0&&t[1]>=1440?'24 hours':rrClock(t[0])+'–'+rrClock(t[1]),wk=f(h.wk),sat=f(h.sat),sun=f(h.sun);
 return wk===sat&&sat===sun?[['Daily',wk]]:[['Mon–Fri',wk],['Saturday',sat],['Sunday',sun]];
}
function rrFacilityIcon(name){
 if(name==='RR Services')return `<svg class="fac-rr" viewBox="0 0 108 50" aria-hidden="true"><use href="#rr-service-mark"></use></svg>`;
 const kind=ICONS[name]||ICONS[facilityLabel(name)];return kind?`<svg viewBox="0 0 32 32" aria-hidden="true"><use href="#rr-picto-${kind}"></use></svg>`:'';
}
// A facility with opening hours is a button: its dot shows open/closed now, and a tap opens the hours under its row.
function rrFacilityTile(name,hours,fault){
 if(fault)return `<button type="button" class="facility has-hours" data-fac="${name}" aria-expanded="false"><span class="fac-icon">${rrFacilityIcon(name)}<i class="fac-dot fault" aria-hidden="true"></i></span><span>${pictoLabel(name)}</span></button>`;
 if(!hours)return pictoItem(name);
 const st=rrOpenStatus(hours);
 return `<button type="button" class="facility has-hours" data-fac="${name}" aria-expanded="false"><span class="fac-icon">${rrFacilityIcon(name)}<i class="fac-dot${st.open?' open':''}" aria-hidden="true"></i></span><span>${name}</span></button>`;
}
function rrFaultDetail(name,fault){
 return `<div class="fac-detail"><div class="fac-detail-head"><span class="fac-detail-icon">${rrFacilityIcon(name)}</span><div><strong>${pictoLabel(name)}</strong><span class="fac-status fault">${fault.title}</span></div></div><p class="fac-note">${fault.text}</p><dl class="fac-hours"><div><dt>Expected back</dt><dd>${rrClock(fault.back)}</dd></div></dl></div>`;
}
function rrFacilityDetail(name,hours){
 const st=rrOpenStatus(hours);
 return `<div class="fac-detail"><div class="fac-detail-head"><span class="fac-detail-icon">${rrFacilityIcon(name)}</span><div><strong>${name}</strong><span class="fac-status${st.open?' open':''}">${st.text}</span></div></div>${RR_FAC_NOTE[name]?`<p class="fac-note">${RR_FAC_NOTE[name]}</p>`:''}<dl class="fac-hours">${rrHoursRows(hours).map(([d,t])=>`<div><dt>${d}</dt><dd>${t}</dd></div>`).join('')}</dl></div>`;
}
function rrWireFacilityHours(root,hoursOf,faultOf){
 root.querySelectorAll('.facility.has-hours').forEach(btn=>btn.addEventListener('click',()=>{
  const grid=btn.parentElement,open=btn.getAttribute('aria-expanded')==='true';
  grid.querySelectorAll('.fac-detail').forEach(x=>x.remove());grid.querySelectorAll('.has-hours').forEach(b=>b.setAttribute('aria-expanded','false'));
  if(open)return;
  const tiles=[...grid.children],row=tiles.filter(t=>t.offsetTop===btn.offsetTop),last=row[row.length-1];
  const f=btn.dataset.fac,fault=faultOf?.(f);
  last.insertAdjacentHTML('afterend',fault?rrFaultDetail(f,fault):rrFacilityDetail(f,hoursOf(f)));btn.setAttribute('aria-expanded','true');
 }));
}
function pictoLabel(name){return ({'Accessible Toilet':'Accessible toilet','Baby Changing':'Baby changing','Reserved Seats':'Reserved seats','Quiet Zone':'Quiet zone','First Class':'First class','Premium Class':'Premium class'})[name]||name}
function pictoItem(name){
 const kind=ICONS[name]||ICONS[facilityLabel(name)];if(!kind)return '';
 const label=pictoLabel(name);
 return `<div class="facility" title="${label}"><svg viewBox="0 0 32 32" aria-hidden="true"><use href="#rr-picto-${kind}"></use></svg><span>${label}</span></div>`;
}
const STATION_CORE=['Information','Accessible','Accessible Toilet','Toilet','Lift','Escalator'];
const STATION_AMENITIES={
 national:['Interchange','Café','Dining','Wi-Fi','Luggage','Cycles','Baby Changing','Family'],
 major:['Interchange','Café','Dining','Wi-Fi','Luggage','Cycles','Baby Changing','Family'],
 regional:['Interchange','Café','Wi-Fi','Luggage','Baby Changing'],
 local:['Café','Wi-Fi']
};
function stationFacilities(name){
 const airport=AIRPORT_STATIONS.has(name);
 // The PDF defines major stations; a generic "Central" suffix is not proof
 // of major status (e.g. Medway Central is a smaller station on this map).
 const tier=rrStationTier(name);
 const items=[...STATION_CORE,...STATION_AMENITIES[tier]];
 if(airport)for(const item of ['Airport','Interchange','Luggage','Baby Changing'])items.push(item);
 return [...new Set(items)];
}
function trainFacilities(train){
 const items=[...new Set(train.fac.map(facilityLabel))];
 if(items.includes('Accessible')&&items.includes('Toilet')&&!items.includes('Accessible Toilet'))items.push('Accessible Toilet');
 return items;
}
// Services calling at a station: one row per service (Regio per network). Regio rows open to list their lines; Mainline numbers are not routes, so they are not listed.
function rrStationServices(name){
 const m=new Map(),order=['Max','VIA','InterCity','Nightline','Regio'];
 for(const t of TRAINS){const i=t.route.findIndex(r=>r[0]===name);if(i<0)continue;
  const k=t.type+'|'+(t.network||'');if(!m.has(k))m.set(k,{type:t.type,network:t.network||'',badges:new Map()});
  const e=m.get(k),l=rrTrainLabel(t);if((t.type==='Regio'||t.type==='Local')&&!e.badges.has(l))e.badges.set(l,t)}
 return [...m.values()].sort((a,b)=>order.indexOf(a.type)-order.indexOf(b.type));
}
/* Route details: one Regio or Local line on one network. Next departures from the station you came from (3 each way),
   and a line diagram of the whole route with one lane per stopping pattern (RS stops everywhere, RX only at its stops). */
function fillRouteInfo(type,net,line,from=currentStation){
 // Lanes: RX and RS for a Regio line; every branch of a Local letter line (A1, A2…); otherwise the line itself.
 // (Havenbolme S-lines are separate lines, not branches.)
 const branchOf=l=>String(l).replace(/\d+/g,''),branched=type==='Local'&&net!=='Havenbolme';
 const trains=TRAINS.filter(t=>t.type===type&&t.network===net&&(branched?branchOf(t.line)===branchOf(line):t.line===line));if(!trains.length)return;
 const keyOf=t=>type==='Regio'?t.pattern:t.line;
 let lanes=type==='Regio'?['RX','RS'].filter(p=>trains.some(t=>t.pattern===p)):[...new Set(trains.map(t=>t.line))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
 const dir1=k=>trains.filter(t=>keyOf(t)===k&&t.dir===1).sort((a,b)=>b.route.length-a.route.length)[0];
 lanes=lanes.filter(k=>dir1(k));
 const runs=Object.fromEntries(lanes.map(k=>[k,dir1(k).route.map(r=>r[0])])),stopsOf=Object.fromEntries(lanes.map(k=>[k,new Set(runs[k])]));
 // one station list for all lanes: the longest lane, then each other lane's own stations where they belong;
 // a branch stored the other way round is turned to face the same way first
 const all=[...runs[[...lanes].sort((a,b)=>runs[b].length-runs[a].length)[0]]];
 for(const k of lanes){const ix=runs[k].map(n=>all.indexOf(n)).filter(i=>i>=0);if(ix.length>1&&ix[0]>ix[ix.length-1])runs[k]=[...runs[k]].reverse()}
 for(const k of lanes){let cur=-1,pending=[];
  for(const n of runs[k]){const at=all.indexOf(n);
   if(at<0){pending.push(n);continue}
   if(pending.length){all.splice(cur<0?at:cur+1,0,...pending);pending=[]}
   cur=all.indexOf(n)}
  if(pending.length)all.splice(cur+1,0,...pending)}
 const sample=Object.fromEntries(lanes.map(k=>[k,trains.find(t=>keyOf(t)===k)]));
 const span=Object.fromEntries(lanes.map(k=>{const ix=runs[k].map(n=>all.indexOf(n));return [k,[Math.min(...ix),Math.max(...ix)]]}));
 rrDetailsHeading('Route details','rr-ui-route');$('focusRoute').hidden=true;
 let deps='';
 if(all.includes(from)){
  const up=upcoming(from).filter(t=>trains.includes(t)||(t.type===type&&t.network===net&&lanes.includes(keyOf(t))&&(type!=='Regio'||t.line===line))),groups=new Map();
  for(const t of up){if(!groups.has(t.dest))groups.set(t.dest,[]);if(groups.get(t.dest).length<3)groups.get(t.dest).push(t)}
  deps=`<section class="rr-card"><h3 class="rr-card-title">Next departures from ${from}</h3>${[...groups].map(([dest,list])=>`<div class="route-dir"><div class="rr-card-sub">Towards ${dest}</div>${list.map(t=>`<button type="button" class="route-dep" data-train="${t.id}"><span class="route-dep-time">${stopTimeMarkup(t,t.hereIndex)}</span>${rrBadge(t)}<span class="route-dep-main"><span class="route-dep-dest">${t.dest}</span><span class="route-dep-status">${statusTag(rrBoardStatus(t,false))}</span></span><span class="route-dep-plat" title="Platform">${rrBoardPlatform(t,from)}</span></button>`).join('')}</div>`).join('')||'<div class="rr-card-sub">No more departures today.</div>'}</section>`;
 }
 const many=lanes.length>1;
 const rows=all.map((n,i)=>`<div class="route-row${n===from?' is-here':''}${many&&lanes.every(k=>stopsOf[k].has(n))?' all-stop':''}">${lanes.map(k=>{const [a,b]=span[k];return `<span class="route-lane lane-${k}${stopsOf[k].has(n)?' stops':''}${i<a||i>b?' off':''}${i===a?' first':''}${i===b?' last':''}"></span>`}).join('')}<button type="button" class="route-stn" data-station="${n}">${n}</button></div>`).join('');
 // termini: the two ends of the line, each listing its terminus (one per branch when the line branches there)
 const inner=new Set(lanes.flatMap(k=>runs[k].slice(1,-1)));
 const ends=[0,1].map(side=>{const e=[...new Set(lanes.map(k=>side?runs[k][runs[k].length-1]:runs[k][0]))],outer=e.filter(n=>!inner.has(n));return outer.length?outer:e});
 const legend=type==='Regio'&&many?`<div class="route-legend">${lanes.map(k=>`<span>${rrBadge(sample[k])} ${k==='RS'?'all stations':'main stations only'}</span>`).join('')}<span class="route-legend-map"><span class="map-key-rx" aria-hidden="true"></span>RX stop<span class="map-key-rs" aria-hidden="true"></span>RS only</span></div>`
  :'';
 detail.innerHTML=`<div class="train-hero route-hero" data-route="${type}|${net}|${line}"><div class="route-badges">${(type==='Regio'?lanes:[lanes[0]]).map(k=>rrBadge(sample[k])).join('')}</div><div class="route-op">${rrServiceLabel(type,net)}</div>${`<div class="route-termini" style="--route:${rrTrainCss(sample[lanes[0]])}" aria-label="Runs between ${ends[0].join(' or ')} and ${ends[1].join(' or ')}">${ends.map(e=>`<div class="route-end"><span class="route-end-dot" aria-hidden="true"></span><span class="route-end-name">${e.map(rrStnLink).join(' · ')}</span></div>`).join('')}</div>`}</div>${deps}<section class="rr-card" style="--route:${rrTrainCss(sample[lanes[0]])}"><h3 class="rr-card-title">Route</h3>${legend}<div class="route-diagram" style="--route:${rrTrainCss(sample[lanes[0]])};--lanes:${lanes.length}">${rows}</div></section>`;
 detail.querySelectorAll('.route-dep').forEach(b=>b.addEventListener('click',()=>{const row=upcoming(from).find(t=>t.id===b.dataset.train);if(row){setCurrentStation(from);chooseTrain(row)}}));
 detail.querySelectorAll('.route-stn').forEach(b=>b.addEventListener('click',()=>{setCurrentStation(b.dataset.station);fillStationInfo(b.dataset.station)}));
 // the map shows the whole line: every branch, in the line colour; RS-only stops get a small dot, RX stops a ring
 const full=lanes.map(dir1).sort((a,b)=>b.route.length-a.route.length)[0];
 selectedJourney=null;selectedLegPaths=[];selectedTrain=null;manualTrace=false;routeColor=rrMapColor(full);
 if(branched&&many){selectedLegPaths=lanes.map(k=>({path:getTrainPath(dir1(k)),color:routeColor}));selectedPath=selectedLegPaths.flatMap(p=>p.path)}
 else selectedPath=getTrainPath(full);
 selectedNames=all;selectedRouteLine=full;
 rrRouteMinor=type==='Regio'&&stopsOf.RX&&stopsOf.RS?new Set(runs.RS.filter(n=>!stopsOf.RX.has(n))):new Set();
 drawBoard();drawRoute();drawMap();
 detail.scrollTop=0;app.classList.add('detail-open');requestAnimationFrame(()=>{resize();focusRoute()});rrSyncHash();
}
function fillStationInfo(name=currentStation, returnTrain=null, returnJourney=null){
 rrDetailsHeading('Station information','rr-ui-info');$('focusRoute').hidden=true;
 const facilities=stationFacilities(name);
 const additional=facilities.filter(f=>!STATION_CORE.includes(f));
 const hours=STATION_HOURS[rrStationTier(name)],help=STATION_HELP.filter(f=>hours[f]),fault=rrStationFault(name);
 const backButton=returnTrain?`<button type="button" class="back-to-train" id="backToTrain" aria-label="Back to train ${rrTrainLabel(returnTrain.train)}"><span aria-hidden="true"><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-left"></use></svg></span><span>Back to</span>${rrBadge(returnTrain.train)}</button>`:returnJourney?`<button type="button" class="back-to-train" id="backToJourney"><span aria-hidden="true"><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-left"></use></svg></span><span>Back to journey</span></button>`:'';
 const svc=rrStationServices(name),plats=new Set(TRAINS.map(t=>t.platforms?.[name]).filter(Boolean));
 detail.innerHTML=`${backButton}<div class="train-hero station-hero" data-station="${name}"><div class="station-name-band">${name}</div><div class="station-actions">${[['departures','Departures'],['arrivals','Arrivals'],['from','Journey from here'],['to','Journey to here']].map(([k,l])=>`<button type="button" class="station-action" data-action="${k}"><span>${l}</span><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-right"></use></svg></button>`).join('')}</div></div>
 <section class="rr-card"><h3 class="rr-card-title">Services</h3><div class="station-services">${svc.map(s=>!s.badges.size?`<div class="station-svc"><div class="station-svc-row"><span class="station-svc-name">${rrServiceLabel(s.type,s.network)}</span></div></div>`:`<details class="station-svc"><summary><span class="station-svc-name">${rrServiceLabel(s.type,s.network)}</span><span class="jt-chevron" aria-hidden="true"></span></summary><div class="station-svc-lines">${[...s.badges.entries()].sort((a,b)=>a[0].localeCompare(b[0],undefined,{numeric:true})).map(([,t])=>`<button type="button" class="route-link" data-route-type="${t.type}" data-route-net="${t.network}" data-route-line="${t.line}" title="Route details">${rrBadge(t)}</button>`).join('')}</div></details>`).join('')}</div>${plats.size?`<div class="station-svc-foot">${plats.size} platforms</div>`:''}</section>
 <section class="rr-card"><h3 class="rr-card-title">Facilities</h3>${help.length?`<h4 class="rr-card-sub">Help and services</h4><div class="station-picto-grid">${help.map(f=>rrFacilityTile(f,hours[f])).join('')}</div>`:''}<h4 class="rr-card-sub" data-rr-fr="Standard">Standard</h4><div class="station-picto-grid">${STATION_CORE.map(f=>rrFacilityTile(f,null,fault?.facility===f?fault:null)).join('')}</div>
 ${additional.length?`<h4 class="rr-card-sub" data-rr-fr="Supplémentaires">Additional</h4><div class="station-picto-grid">${additional.map(f=>rrFacilityTile(f,hours[f],fault?.facility===f?fault:null)).join('')}</div>`:''}</section>`;
 rrWireFacilityHours(detail,f=>hours[f],f=>fault?.facility===f?fault:null);
 detail.querySelectorAll('.route-link').forEach(b=>b.addEventListener('click',()=>fillRouteInfo(b.dataset.routeType,b.dataset.routeNet,b.dataset.routeLine,name)));
 detail.querySelectorAll('.station-action').forEach(b=>b.addEventListener('click',()=>{
  const k=b.dataset.action;
  if(k==='departures'||k==='arrivals'){viewMode=k;setCurrentStation(name);return}
  rrSelectValue($(k),name);pickerViews.get(k)?.sync();setViewMode('journeys');
 }));
 if(returnTrain){
  $('backToTrain').addEventListener('click',()=>{
   viewMode=returnTrain.boardMode==='arrivals'?'arrivals':'departures';
   setCurrentStation(returnTrain.station);
   const stationTrains=viewMode==='arrivals'?arriving(returnTrain.station):upcoming(returnTrain.station);
   const restored=stationTrains.find(candidate=>candidate.id===returnTrain.train.id)||returnTrain.train;
   chooseTrain(restored,true);
  });
 }
 if(returnJourney){$('backToJourney').addEventListener('click',()=>{viewMode='journeys';updateBoardTabs();chooseJourney(returnJourney)})}
 detail.scrollTop=0;
 app.classList.add('detail-open');
 requestAnimationFrame(resize);
 rrSyncHash();
}

$('stationInfoLeft').addEventListener('click',()=>fillStationInfo(currentStation));

